fn total_len(items: &[String]) -> usize {
    items.iter().map(|s| s.len()).sum()
}

fn main() {
    let names = vec![String::from("ada"), String::from("grace")];
    println!("{}", total_len(&names)); // borrowed — names still usable
    println!("count: {}", names.len());
}

