fn shout_all(names: Vec<String>) {
    for n in &names {
        println!("{}", n.to_uppercase());
    }
}

fn main() {
    let mut names = vec![String::from("ada"), String::from("grace")];
    shout_all(names.clone());
    for n in names.clone() {
        println!("{n}");
    }
    let _ = names;
}

exercise.solution:
fn shout_all(names: &[String]) {
    for n in names {
        println!("{}", n.to_uppercase());
    }
}

fn main() {
    let names = vec![String::from("ada"), String::from("grace")];
    shout_all(&names);
    for n in &names {
        println!("{n}");
    }
}
